function methods(){return head('模型與資料','可追溯、可重現，與限制一起公開。')+`<div class="prose"><section><h2>證據、模型與情境分層</h2><p>本版增加訓練資料內的縣市分組選參、支持關係代理與多方案兵推。${esc(data.support_model.note)}未解決的模型缺項標為D級；已使用的代理仍需核對其假設。${esc(data.evidence.grading_rule)}</p><p>快速情境是明示參數的敏感度分析，不是AI虛擬選民民調。尚未上線自動新聞理解、人口分群、投票率模型或政治心理推斷。規則摘要只描述資料覆蓋與已知缺項，不生成無來源的選情判斷。</p><p>動態頁存檔保留每個台北日期、每個產品版本的最後一次基準摘要，最多180筆。缺日不插值；摘要不含完整抽樣，完整重現仍需下載當次模型快照。</p></section><section><h2>候選人級基本面</h2><p>使用上傳中選會2014、2018、2022共66場、271筆候選人原始票數；以2014作為初始歷史特徵，從2018、2022共44場資料重新訓練ridge，以前屆個人及具名政黨得票、前屆勝方與缺資料標記為特徵。所有特徵只讀取較早年份。多名無黨籍分別預測。正式黨籍不因背書改變，席次在選出勝方後才加總；有來源的支持組織只用於先驗特徵。每個前屆政黨票池在當屆有相同組織連結的人選之間分配一次，避免重複加總。</p></section><section><h2>動態民調與共享誤差</h2><p>在候選人中心化對數比例空間，建立全台、區域及地方協方差。民調以正交對比進行聯合高斯更新，保留同機構相關偏差與重疊時間的變動誤差；一縣市的觀測可經共享協方差影響其他縣市。自訪問期間中點至目前、至投票日的時間差均參與不確定性計算。</p><p>這是條件於明示超參數的高斯近似，不是完整MCMC分層後驗。TVBS歷史波次已用於誤差尺度訓練與2022留出檢驗；單一機構不足以分別估計機構、模式和母體效應，保留原有誤差下限。</p></section><section><h2>不完整題目與未表態</h2><p>只觀測題目列出人選的相對支持，並為不完整對決加入額外誤差。這仍假設人選相對支持可移植到登記名單，可能存在選項效應；未列人選保留先驗而非設為零。加權百分比不冒充原始票數；未表態保留原值，折減有效樣本並擴大測量誤差，未推定其最終分配。</p></section><section><h2>票流與條件機率</h2><p>支持變化按其他候選人當次比例轉移，票流守恆。票流矩陣可同時指定多個來源與去向，另可只重分配相對基準減少的支持。策略投票以基準期排名為訊號，可按前二差距衰減，並指定流向前二的比例，不使用未來抽樣排名。指定席次僅改結果統計；條件勝選則篩選整批聯合抽樣並公布保留數，兩者不混用。</p></section><section><h2>公開參數</h2><div class="table-wrap"><table><thead><tr><th>參數</th><th>數值</th></tr></thead><tbody>${Object.entries(data.settings).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${v}</td></tr>`).join('')}</tbody></table></div><p>日變異、機構、未表態與選項效應尺度尚待跨週期估計；區間不能當成已校準的信賴保證。</p></section><section><h2>自動更新與重現</h2><p>GitHub Actions每6小時抓取並校驗原始報告，再訓練、推論及發布同一資料版本。瀏覽器每10分鐘讀取成對的模型與民調資料，失敗時保留最後有效版本。沒有新報告時不製造新民調；選前暫停發布沿用既有設定。</p><p>版本 ${esc(data.model_version)}；登記名單 ${esc(data.roster_as_of)}。分享連結保存假設，資料更新後會提醒；下載快照保留資料、參數和情境，可重現當次結果。</p><button id="export">下載完整快照</button></section><section><h2>方法參考與限制</h2><p><a href="https://otexts.com/fpp3/tscv.html">Hyndman：時間順序驗證</a>；<a href="https://sites.stat.columbia.edu/gelman/research/published/Harvard_Data_Science_Review.pdf">Heidemanns等：動態選舉預測</a>。採用方法思想，未照搬美國模型係數。</p>${data.limitations.map(s=>`<p>${esc(s)}</p>`).join('')}<a href="research-legacy.html">舊版三方研究頁</a> · <a href="legacy.html">舊版進階工作台</a></section></div>`;}
const WORKSPACE_KEY='tw-candidate-scenario-studio-v1';
function readWorkspace(){try{return JSON.parse(localStorage.getItem(WORKSPACE_KEY)||'null');}catch{return null;}}
function saveWorkspace(){try{localStorage.setItem(WORKSPACE_KEY,JSON.stringify(workspace.serialize()));}catch{notice('瀏覽器無法儲存方案，請使用匯出功能。');}}
function downloadPlans(){const url=URL.createObjectURL(new Blob([JSON.stringify(workspace.serialize(),null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='election-scenarios.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function importPlans(file){if(!file)return;try{if(file.size>2000000)throw Error('方案檔案超過2MB');const saved=JSON.parse(await file.text());if(saved.schema_version!==1||!saved.slots)throw Error('請選擇匯出的方案JSON');for(const id of ['A','B','C']){if(!saved.slots[id]?.state)throw Error('缺少方案');analyze(data,cleanState(saved.slots[id].state,data));}const next=workspace.restore(saved);commit(next,false);if(saved.fingerprint!==data.fingerprint)notice('方案使用不同資料版本，已依目前名單及模型重算。');}catch(e){notice('匯入失敗：'+e.message);}}
function historyDownload(){const blob=new Blob([snapshotDownload(data)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='forecast-history-summaries.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function previewPreset(id){try{const p=PRESETS.find(x=>x.id===id);pendingPreset=presetState(data,state.county,id,editState());$('#presetDescription').textContent=p.description+' 本情境使用 '+state.county+' 的目前人選選擇，清除其他使用者調整與勝方設定。';$('#presetDialog').showModal();}catch(e){notice(e.message);}}
function stopHistoryPlayback(update=true){historyPlaying=false;clearTimeout(historyTimer);historyTimer=null;if(update&&view==='updates'){const timeline=$('.history-timeline');if(timeline)timeline.outerHTML=historyTimeline();}}
function updateHistorySurface(){if(view!=='updates')return;const frame=activeHistoryFrame(),deltas={};updateElectionMapFrame(geo,result.counties,data.counties,baseline.counties,'leader',deltas,frame.overrides);const map=$('#countyMap');if(map){map.dataset.historyYear=String(historyYear);map.dataset.historyMetric=historyMetric;}const inspectorPane=$('#historyInspector');if(inspectorPane)inspectorPane.innerHTML=historyInspector();const timelinePane=$('.history-timeline');if(timelinePane)timelinePane.outerHTML=historyTimeline();const modePane=$('.history-mode-control');if(modePane)modePane.outerHTML=historyModeControl();const legend=$('.history-map-stage .gis-legend');if(legend)legend.innerHTML=historyLegend()+`<span class="gis-height-key" ${perspective==='3d'?'':'hidden'}>${historyMetric==='swing'?'高度＝相對前屆變動':'高度＝勝方差距'}</span>`;const period=$('#historyAtlasPeriod'),metric=$('#historyAtlasMetric'),level=$('#gisLevelIndicator small'),viewLabel=$('.gis-perspective-control small');if(period)period.textContent=historyYear===2026?'2026 模型預測':historyYear+' 地方選舉';if(metric)metric.textContent=historyMetric==='swing'?'相對前屆兩黨差額':'縣市勝方與差距';if(level)level.textContent=historyYear===2026?'2026 模型預測':'中選會實際結果';if(viewLabel)viewLabel.textContent=perspective==='3d'?(historyMetric==='swing'?'高度＝相對前屆變動':'高度＝勝方差距'):'正北俯視';writeRoute();}
function scheduleHistoryStep(){clearTimeout(historyTimer);if(!historyPlaying)return;historyTimer=setTimeout(()=>{historyYear=nextHistoryYear(historyYear);if(historyYear===2014&&historyMetric==='swing')historyMetric='result';if(historyYear===2026)historyPlaying=false;updateHistorySurface();if(historyPlaying)scheduleHistoryStep();},1500);}
function toggleHistoryPlayback(){if(historyPlaying){stopHistoryPlayback();return;}if(historyYear===2026){historyYear=2014;if(historyMetric==='swing')historyMetric='result';}historyPlaying=true;updateHistorySurface();scheduleHistoryStep();}
function render(){document.querySelectorAll('.studio-details').forEach(d=>{const key=d.querySelector('summary')?.textContent;if(d.open)openStudioDetails.add(key);else openStudioDetails.delete(key);});document.querySelectorAll('.topbar [data-view]').forEach(a=>a.setAttribute('aria-current',a.dataset.view===view?'page':'false'));$('#page').innerHTML=({overview,counties,updates:historyAtlas,polls,scenario,validation:validationPage,methods}[view])();document.querySelectorAll('.studio-details').forEach(d=>{d.open=openStudioDetails.has(d.querySelector('summary')?.textContent);});draw();document.title=`${{overview:'總覽',counties:'候選人',updates:'歷史選舉 GIS',polls:'民調',scenario:'兵推',validation:'驗證',methods:'方法'}[view]} | 台灣選舉觀測`;}
function commit(next,remember=true){try{const updated=analyze(data,next);if(workspace)workspace.change(updated.state,remember);state=updated.state;result=updated;writeRoute();render();notice(result.acceptance<1?`條件抽樣保留${result.simulations}次（${pct(result.acceptance)}）。`:'已同步更新候選人、地圖與席次。');}catch(e){notice(e.message);render();}}
async function refresh(quiet=false){if(refreshing)return;refreshing=true;try{const d=await get('candidate-model.json'),f=await get('polls.json'),r=await get('candidate-validation.json');validate(d);if(d.feed_checked_at!==f.checked_at||d.training_data_hash!==r.data_hash||d.fingerprint!==r.model_fingerprint||d.historical_poll_hash!==r.historical_polling?.data_hash)throw Error('模型與民調資料版本尚未同步');if(paused(d)){pause();return;}const updated=analyze(d,cleanState(state,d));data=d;feed=f;research=r;if(workspace)workspace.rebase(d);baseline=analyze(d);result=updated;state=updated.state;render();if(!quiet)notice('已讀取雲端有效資料。');}catch(e){if(!quiet)notice(`${e.message}，保留最後有效資料。`);}finally{refreshing=false;}}
function exportData(){const blob=new Blob([JSON.stringify({schema_version:2,data,feed,research,state,result,workspace:workspace?.serialize()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`candidate-forecast-${data.fingerprint.slice(0,12)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',e=>{const filter=e.target.closest('[data-rating-filter]'),close=e.target.closest('[data-close-race]'),county=e.target.closest('[data-county]'),geoBack=e.target.closest('[data-geo-back]'),nav=e.target.closest('[data-view]');if(filter){e.preventDefault();e.stopPropagation();ratingFilter=filter.dataset.ratingFilter;const panel=$('.command-ratings');if(panel)panel.outerHTML=ratingsTable();return;}if(close&&view==='overview'){e.preventDefault();e.stopPropagation();detailOpen=false;geography=null;updateCommandAside();return;}if(nav?.dataset.view==='overview')detailOpen=false;if(view==='overview'&&county){detailOpen=true;const pane=$('#inspector');if(pane)pane.className='inspector district-inspector is-race-detail';}if(view==='overview'&&(e.target.closest('#mapReset')||geoBack?.dataset.geoBack==='national'))detailOpen=false;},true);
document.addEventListener('click',e=>{const slot=e.target.closest('[data-slot]'),inputTab=e.target.closest('[data-input-panel]'),resultTab=e.target.closest('[data-result-panel]'),historyYearButton=e.target.closest('[data-history-year]'),historyMetricButton=e.target.closest('[data-history-metric]');if(historyYearButton){stopHistoryPlayback(false);historyYear=Number(historyYearButton.dataset.historyYear);if(historyYear===2014&&historyMetric==='swing')historyMetric='result';updateHistorySurface();return;}if(historyMetricButton){stopHistoryPlayback(false);historyMetric=historyMetricButton.dataset.historyMetric;updateHistorySurface();return;}if(e.target.closest('[data-history-play]')){toggleHistoryPlayback();return;}if(slot){try{analyze(data,workspace.slots[slot.dataset.slot].state);commit(workspace.use(slot.dataset.slot),false);}catch(error){notice(error.message);}return;}if(inputTab){inputPanel=inputTab.dataset.inputPanel;render();return;}if(resultTab){resultPanel=resultTab.dataset.resultPanel;render();return;}if(e.target.id==='undoScenario'){commit(workspace.undo(),false);return;}if(e.target.id==='redoScenario'){commit(workspace.redo(),false);return;}if(e.target.id==='duplicateScenario'){try{commit(workspace.duplicate(),false);}catch(error){notice(error.message);}return;}if(e.target.id==='downloadPlans'){downloadPlans();return;}if(e.target.id==='clearMatrix'){const next=structuredClone(state);next.edits[rawRace().race_id]={...editState(),matrix:[]};commit(next);return;}const preset=e.target.closest('[data-preset]');if(preset){previewPreset(preset.dataset.preset);return;}if(e.target.id==='applyPreset'){const next=pendingPreset;$('#presetDialog').close();pendingPreset=null;if(next)commit(next);return;}if(e.target.id==='cancelPreset'){$(`#presetDialog`).close();pendingPreset=null;return;}if(e.target.id==='downloadHistory'){historyDownload();return;}if(['currentPollTab','historicalPollTab'].includes(e.target.id)){pollArchive=e.target.id==='historicalPollTab';render();return;}if(e.target.closest('[data-jump-candidates]')){$('#raceCandidates')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});return;}const nav=e.target.closest('[data-view]'),county=e.target.closest('[data-county]'),m=e.target.closest('[data-mode]'),base=e.target.closest('[data-basemap]'),dimension=e.target.closest('[data-perspective]'),jump=e.target.closest('[data-view-jump]'),geoBack=e.target.closest('[data-geo-back]');if(nav){e.preventDefault();stopHistoryPlayback(false);view=nav.dataset.view;if(view!=='scenario'&&mode==='flow')mode='leader';writeRoute(true);render();scrollTo(0,0);return;}if(jump){stopHistoryPlayback(false);view=jump.dataset.viewJump;writeRoute(true);render();scrollTo(0,0);return;}if(geoBack){if(geoBack.dataset.geoBack==='national'){view==='counties'?focusElectionCounty(state.county):resetElectionMap();return;}stepBackElectionMap();return;}if(county){state.county=county.dataset.county;geography=null;writeRoute();if(view==='updates'){const pane=$('#historyInspector');if(pane)pane.innerHTML=historyInspector();focusElectionCounty(state.county);return;}if($('#inspector')){$('#inspector').innerHTML=inspector();focusElectionCounty(state.county);}else render();return;}if(m){mode=m.dataset.mode;writeRoute();render();return;}if(base){basemap=base.dataset.basemap;writeRoute();render();return;}if(dimension){perspective=dimension.dataset.perspective;document.querySelectorAll('[data-perspective]').forEach(button=>button.setAttribute('aria-pressed',String(button===dimension)));const label=$('.gis-perspective-control small');if(label)label.textContent=view==='updates'?(perspective==='3d'?(historyMetric==='swing'?'高度＝相對前屆變動':'高度＝勝方差距'):'正北俯視'):(perspective==='3d'?'高度＝領先方勝率':'正北俯視');const heightKey=$('.gis-height-key');if(heightKey)heightKey.hidden=perspective!=='3d';setElectionPerspective(perspective);writeRoute();return;}if(e.target.id==='mapReset'){view==='counties'?focusElectionCounty(state.county):resetElectionMap();return;}if(e.target.closest('#sheetHandle')){e.target.closest('.district-inspector,.history-inspector')?.classList.toggle('is-expanded');return;}if(e.target.id==='reset')commit({county:state.county});if(e.target.id==='reloadPolls')refresh();if(e.target.id==='export')exportData();if(e.target.id==='share'){if(location.href.length>8000){notice('方案連結過長，請匯出方案檔案分享。');return;}$('#shareUrl').value=location.href;$('#shareDialog').showModal();}if(e.target.id==='closeShare')$('#shareDialog').close();if(e.target.id==='copyLink')navigator.clipboard.writeText($('#shareUrl').value).then(()=>notice('已複製連結。')).catch(()=>notice('請手動複製已選取的連結。'));});
document.addEventListener('click',e=>{if(!e.target.closest('[data-perspective]'))return;const label=$('.gis-perspective-control small');if(label)label.textContent=perspective==='3d'?'地形＝20m DTM · 柱高＝勝率':'正北俯視';});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='planName'){workspace.slots[workspace.active].name=t.value.trim().slice(0,32)||'方案 '+workspace.active;saveWorkspace();render();return;}if(t.id==='importPlans'){importPlans(t.files?.[0]);return;}if(t.dataset.matrixFrom){const value=Number(t.value),current=editState(),from=t.dataset.matrixFrom,to=t.dataset.matrixTo,others=(current.matrix||[]).filter(x=>!(x.from===from&&x.to===to));if(!Number.isFinite(value)||value<0||value>100||others.filter(x=>x.from===from).reduce((s,x)=>s+x.rate,0)+value>100){t.setAttribute('aria-invalid','true');notice('每個來源的總移轉比例不可超過100%。');return;}const next=structuredClone(state);next.edits[rawRace().race_id]={...current,matrix:[...others,{from,to,rate:value}]};commit(next);return;}if(['matrixMode','strategy'].includes(t.id)){const next=structuredClone(state);next.edits[rawRace().race_id]={...editState(),[t.id]:t.value};commit(next);return;}if(t.id==='historyCompare'){historyCompare=t.value;render();return;}if(t.id==='historyYear'){historyFilters.year=Number(t.value);historyFilters.county='all';render();}if(t.id==='historyCounty'){historyFilters.county=t.value;render();}if(t.id==='historyEligible'){historyFilters.eligible=t.checked;render();}if(t.id==='validationHorizon'){validationHorizon=Number(t.value);render();}if(['county','studioCounty'].includes(t.id)){state.county=t.value;geography=null;writeRoute();render();}if(t.id==='seatGroup'){seatGroup=t.value;render();}if(t.id==='pollCounty'){pollCounty=t.value;render();}if(t.id==='pollSource'){pollSource=t.value;render();}if(t.id==='includedOnly'){includedOnly=t.checked;render();}if(['boostId','from','to'].includes(t.id)){const next=structuredClone(state);next.edits[rawRace().race_id]={...editState(),[t.id]:t.value};commit(next);}if(['constraintMode','constraintCandidate'].includes(t.id)){const next=structuredClone(state),r=rawRace(),mode=$('#constraintMode').value,candidate=$('#constraintCandidate').value;constraintDraft[r.race_id]=candidate;if(mode==='none')delete next.constraints[r.race_id];else next.constraints[r.race_id]={mode,candidate};commit(next);}});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='search'){search=t.value.replaceAll('臺','台');$('#countyTable').innerHTML=countyTable();}if(['boost','flow','tactical','cutoff','topSplit'].includes(t.id)){const next=structuredClone(state);next.edits[rawRace().race_id]={...editState(),[t.id]:Number(t.value)};let updated;try{updated=analyze(data,next);}catch(e){notice(e.message);render();return;}if(workspace)workspace.change(updated.state);state=updated.state;result=updated;writeRoute();$('#'+t.id+'Out').textContent=t.value+(['boost','cutoff'].includes(t.id)?'百分點':'%');if($('#inspector'))$('#inspector').innerHTML=inspector();if($('#strategyHint'))$('#strategyHint').textContent=strategyHint(rawRace(),editState());if($('#undoScenario'))$('#undoScenario').disabled=!workspace.past.length;if($('#redoScenario'))$('#redoScenario').disabled=!workspace.future.length;const band=$('.summary-band');if(band)band.outerHTML=summary();const comparison=$('#scenarioComparison');if(comparison)comparison.outerHTML=scenarioComparison(result,baseline,state.county);if($('#studioOutput')&&resultPanel!=='map')$('#studioOutput').innerHTML=studioOutput();draw();}});
window.addEventListener('popstate',()=>{try{state=urlState();result=analyze(data,state);state=result.state;render();}catch(e){notice(e.message);commit({county:state.county});}});
window.addEventListener('resize',resizeElectionMap);
async function get(path){const r=await fetch(path,{cache:'no-store'});if(!r.ok)throw Error(`${path}無法讀取`);return r.json();}
(async()=>{try{data=validate(await get('candidate-model.json'));if(paused(data)){pause();return;}feed=await get('polls.json');if(feed.checked_at!==data.feed_checked_at)throw Error('模型與民調版本未同步，請稍後重新整理');research=await get('candidate-validation.json');if(research.data_hash!==data.training_data_hash||research.model_fingerprint!==data.fingerprint||research.historical_polling?.data_hash!==data.historical_poll_hash)throw Error('模型與歷史驗證版本未同步');[geo,townResults]=await Promise.all([get('vendor/counties.json'),get('vendor/town-results.json')]);baseline=analyze(data);state=urlState();try{result=analyze(data,state);}catch(e){notice(e.message);state=cleanState({},data);result=analyze(data,state);}state=result.state;workspace=new ScenarioWorkspace(data,state,readWorkspace());writeRoute();$('#loading').hidden=true;render();document.body.dataset.ready='true';window.CandidateApp={get data(){return data;},get result(){return result;},get geography(){return geography;},get perspective(){return perspective;},get workspace(){return workspace.serialize();},drill:drillElectionCoordinates,refresh};setInterval(()=>refresh(true),600000);setInterval(()=>{if(paused(data))pause();},30000);}catch(e){$('#loading').textContent=`載入失敗：${e.message}。請重新整理；原始資料可由頁尾查閱。`;}})();
